  var dirs = [[0, 1], [1, 0], [1, 1], [1, -1]];
  for (var y = 0; y < N; y++) for (var c0 = 0; c0 < N; c0++) {
    var m = x[y][c0];
    if (m == '.') continue;
    for (var d = 0; d < 4; d++) {
      var n = 1;
      while (n < K) {
        var yy = y + dirs[d][0] * n, xx = c0 + dirs[d][1] * n;
        if (yy < 0 || yy >= N || xx < 0 || xx >= N || x[yy][xx] != m) break;
        n++;
      }
      if (n == K) return m;
    }
  }
  return null;
}

"""+s[j:]
